solutionCode:
interface Controllable {
    fun enable()
    fun disable()
}

class Motor(val name: String) : Controllable {
    var isRunning = false

    override fun enable() {
        isRunning = true
    }

    override fun disable() {
        isRunning = false
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testInitialState() {
        val motor = Motor("Left")
        Assert.assertFalse(motor.isRunning)
    }

    @Test
    fun testEnable() {
        val motor = Motor("Left")
        motor.enable()
        Assert.assertTrue(motor.isRunning)
    }

    @Test
    fun testDisable() {
        val motor = Motor("Left")
        motor.enable()
        motor.disable()
        Assert.assertFalse(motor.isRunning)
    }

    @Test
    fun testIsControllable() {
        val motor = Motor("Left")
        Assert.assertTrue(motor is Controllable)
    }
}
